from pathlib import Path
import shutil
import sys
from datetime import datetime

ROOT = Path(__file__).resolve().parent
views_path = ROOT / "core" / "views.py"
template_path = ROOT / "core" / "templates" / "core" / "reminders.html"

required = [views_path, template_path]
missing = [str(p) for p in required if not p.exists()]
if missing:
    print("EROARE: Nu gasesc fisierele necesare:")
    for p in missing:
        print(" -", p)
    print("\nPune acest script in acelasi folder cu manage.py.")
    sys.exit(1)

stamp = datetime.now().strftime("%Y%m%d_%H%M%S")
backup_dir = ROOT / f"backup_toate_reminderele_{stamp}"
backup_dir.mkdir(exist_ok=True)

for src in required:
    rel = src.relative_to(ROOT)
    dst = backup_dir / rel
    dst.parent.mkdir(parents=True, exist_ok=True)
    shutil.copy2(src, dst)

print(f"Backup creat: {backup_dir}")

views = views_path.read_text(encoding="utf-8")

start = views.find("@login_required\ndef lista_reminders(request):")
end = views.find("\ndef adauga_raport_supervizor", start)

if start == -1 or end == -1:
    print("EROARE: Nu am gasit blocul de functii pentru remindere in core/views.py")
    sys.exit(1)

new_reminder_views = '@login_required\ndef lista_reminders(request):\n    if request.user.role not in [\'superadmin\', \'manager\']:\n        return redirect(\'dashboard\')\n\n    reminder_editat = None\n    status_lista = request.GET.get(\'status\', \'active\')\n    afiseaza_finalizate = status_lista == \'finalizate\'\n\n    if request.method == \'POST\':\n        reminder_id = request.POST.get(\'reminder_id\')\n\n        if reminder_id:\n            reminder_editat = get_object_or_404(Reminder, id=reminder_id)\n            form = ReminderForm(request.POST, instance=reminder_editat)\n        else:\n            form = ReminderForm(request.POST)\n\n        if form.is_valid():\n            reminder = form.save(commit=False)\n\n            # La creare, reminderul apartine utilizatorului curent.\n            # La editare, pastram utilizatorul care l-a creat initial.\n            if not reminder_id:\n                reminder.user = request.user\n\n            reminder.save()\n\n            if reminder_id:\n                messages.success(request, "Reminderul a fost actualizat cu succes.")\n            else:\n                messages.success(request, "Reminderul a fost adaugat cu succes.")\n\n            return redirect(\'lista_reminders\')\n    else:\n        reminder_id = request.GET.get(\'edit\')\n\n        if reminder_id:\n            reminder_editat = get_object_or_404(Reminder, id=reminder_id)\n            form = ReminderForm(instance=reminder_editat)\n        else:\n            form = ReminderForm()\n\n    # Managerul si superadminul vad TOATE reminderele.\n    baza = Reminder.objects.select_related(\'user\').all()\n\n    if afiseaza_finalizate:\n        reminders = baza.filter(finalizat=True).order_by(\n            \'-data_finalizarii\',\n            \'-data_reminder\'\n        )\n    else:\n        reminders = baza.filter(finalizat=False).order_by(\'data_reminder\')\n\n    return render(request, \'core/reminders.html\', {\n        \'reminders\': reminders,\n        \'form\': form,\n        \'reminder_editat\': reminder_editat,\n        \'afiseaza_finalizate\': afiseaza_finalizate,\n        \'nr_active\': baza.filter(finalizat=False).count(),\n        \'nr_finalizate\': baza.filter(finalizat=True).count(),\n    })\n\n\n@login_required\ndef finalizeaza_reminder(request, reminder_id):\n    if request.user.role not in [\'superadmin\', \'manager\']:\n        return redirect(\'dashboard\')\n\n    reminder = get_object_or_404(Reminder, id=reminder_id)\n\n    if request.method == \'POST\':\n        reminder.finalizat = True\n        reminder.data_finalizarii = timezone.now()\n        reminder.save(update_fields=[\'finalizat\', \'data_finalizarii\'])\n        messages.success(\n            request,\n            f"Reminderul \'{reminder.titlu}\' a fost marcat ca finalizat."\n        )\n\n    return redirect(\'lista_reminders\')\n\n\n@login_required\ndef reactiveaza_reminder(request, reminder_id):\n    if request.user.role not in [\'superadmin\', \'manager\']:\n        return redirect(\'dashboard\')\n\n    reminder = get_object_or_404(Reminder, id=reminder_id)\n\n    if request.method == \'POST\':\n        reminder.finalizat = False\n        reminder.data_finalizarii = None\n        reminder.save(update_fields=[\'finalizat\', \'data_finalizarii\'])\n        messages.success(\n            request,\n            f"Reminderul \'{reminder.titlu}\' a fost reactivat."\n        )\n\n    return redirect(\'lista_reminders\')\n\n\n@login_required\ndef sterge_reminder(request, reminder_id):\n    if request.user.role not in [\'superadmin\', \'manager\']:\n        return redirect(\'dashboard\')\n\n    reminder = get_object_or_404(Reminder, id=reminder_id)\n    reminder.delete()\n    messages.success(request, "Reminderul a fost sters definitiv.")\n    return redirect(\'lista_reminders\')\n'
views = views[:start] + new_reminder_views + views[end:]
views_path.write_text(views, encoding="utf-8")
print("OK: core/views.py")

template = '{% extends \'core/dashboard.html\' %}\n\n{% block content %}\n<div class="container-fluid mt-4">\n    <div class="d-flex flex-wrap justify-content-between align-items-center gap-2 mb-4">\n        <h2 class="mb-0">🔔 Remindere</h2>\n\n        <div class="d-flex gap-2">\n            {% if afiseaza_finalizate %}\n                <a href="{% url \'lista_reminders\' %}" class="btn btn-primary">\n                    ← Remindere active\n                    <span class="badge bg-light text-primary ms-1">{{ nr_active }}</span>\n                </a>\n            {% else %}\n                <a href="{% url \'lista_reminders\' %}?status=finalizate"\n                   class="btn btn-outline-success">\n                    ✅ Remindere finalizate\n                    <span class="badge bg-success ms-1">{{ nr_finalizate }}</span>\n                </a>\n            {% endif %}\n        </div>\n    </div>\n\n    {% if messages %}\n        {% for message in messages %}\n            <div class="alert alert-{{ message.tags|default:\'success\' }} alert-dismissible fade show"\n                 role="alert">\n                {{ message }}\n                <button type="button" class="btn-close" data-bs-dismiss="alert"></button>\n            </div>\n        {% endfor %}\n    {% endif %}\n\n    {% if not afiseaza_finalizate or reminder_editat %}\n    <div class="card shadow-sm mb-4">\n        <div class="card-body">\n            <h5 class="card-title mb-3">\n                {% if reminder_editat %}\n                    ✏️ Editează reminderul\n                    <small class="text-muted ms-2">\n                        Creat de: {{ reminder_editat.user.username }}\n                    </small>\n                {% else %}\n                    Adaugă un memento nou\n                {% endif %}\n            </h5>\n\n            <form method="POST">\n                {% csrf_token %}\n\n                {% if reminder_editat %}\n                    <input type="hidden" name="reminder_id" value="{{ reminder_editat.id }}">\n                {% endif %}\n\n                <div class="row">\n                    <div class="col-md-4 mb-3">\n                        <label class="form-label">Titlu</label>\n                        {{ form.titlu }}\n                    </div>\n\n                    <div class="col-md-4 mb-3">\n                        <label class="form-label">Data și Ora</label>\n                        {{ form.data_reminder }}\n                    </div>\n\n                    <div class="col-md-12 mb-3">\n                        <label class="form-label">Detalii</label>\n                        {{ form.detalii }}\n                    </div>\n                </div>\n\n                <button type="submit" class="btn btn-primary">\n                    {% if reminder_editat %}\n                        Salvează modificările\n                    {% else %}\n                        Salvează Memento\n                    {% endif %}\n                </button>\n\n                {% if reminder_editat %}\n                    <a href="{% url \'lista_reminders\' %}{% if afiseaza_finalizate %}?status=finalizate{% endif %}"\n                       class="btn btn-outline-secondary ms-2">\n                        Anulează\n                    </a>\n                {% endif %}\n            </form>\n        </div>\n    </div>\n    {% endif %}\n\n    <div class="card shadow-sm">\n        <div class="card-body">\n            <h5 class="card-title mb-3">\n                {% if afiseaza_finalizate %}\n                    ✅ Remindere finalizate\n                {% else %}\n                    Remindere active\n                {% endif %}\n            </h5>\n\n            <div class="table-responsive">\n                <table class="table table-hover align-middle">\n                    <thead class="table-light">\n                        <tr>\n                            <th>Titlu</th>\n                            <th>Creat de</th>\n                            <th>Data reminder</th>\n                            {% if afiseaza_finalizate %}\n                                <th>Finalizat la</th>\n                            {% endif %}\n                            <th>Detalii</th>\n                            <th class="text-center">Acțiune</th>\n                        </tr>\n                    </thead>\n\n                    <tbody>\n                        {% for r in reminders %}\n                        <tr>\n                            <td class="fw-bold">\n                                {% if afiseaza_finalizate %}\n                                    <span class="text-decoration-line-through text-muted">\n                                        {{ r.titlu }}\n                                    </span>\n                                {% else %}\n                                    {{ r.titlu }}\n                                {% endif %}\n                            </td>\n\n                            <td>\n                                <span class="badge bg-secondary">\n                                    {{ r.user.username }}\n                                </span>\n                            </td>\n\n                            <td>{{ r.data_reminder|date:"d M Y, H:i" }}</td>\n\n                            {% if afiseaza_finalizate %}\n                                <td>\n                                    {% if r.data_finalizarii %}\n                                        {{ r.data_finalizarii|date:"d M Y, H:i" }}\n                                    {% else %}\n                                        -\n                                    {% endif %}\n                                </td>\n                            {% endif %}\n\n                            <td>{{ r.detalii }}</td>\n\n                            <td class="text-center text-nowrap">\n                                {% if afiseaza_finalizate %}\n                                    <form method="POST"\n                                          action="{% url \'reactiveaza_reminder\' r.id %}"\n                                          class="d-inline">\n                                        {% csrf_token %}\n                                        <button type="submit"\n                                                class="btn btn-outline-warning btn-sm me-1">\n                                            ↩ Reactivează\n                                        </button>\n                                    </form>\n\n                                    <a href="{% url \'lista_reminders\' %}?status=finalizate&edit={{ r.id }}"\n                                       class="btn btn-outline-primary btn-sm me-1">\n                                        ✏️ Editează\n                                    </a>\n                                {% else %}\n                                    <form method="POST"\n                                          action="{% url \'finalizeaza_reminder\' r.id %}"\n                                          class="d-inline"\n                                          onsubmit="return confirm(\'Marchezi acest reminder ca finalizat?\');">\n                                        {% csrf_token %}\n                                        <button type="submit"\n                                                class="btn btn-success btn-sm me-1">\n                                            ✓ Finalizează\n                                        </button>\n                                    </form>\n\n                                    <a href="{% url \'lista_reminders\' %}?edit={{ r.id }}"\n                                       class="btn btn-outline-primary btn-sm me-1">\n                                        ✏️ Editează\n                                    </a>\n                                {% endif %}\n\n                                <a href="{% url \'sterge_reminder\' r.id %}"\n                                   class="btn btn-outline-danger btn-sm"\n                                   onclick="return confirm(\'Sigur vrei să ștergi definitiv acest reminder?\');">\n                                    Șterge\n                                </a>\n                            </td>\n                        </tr>\n\n                        {% empty %}\n                        <tr>\n                            <td colspan="{% if afiseaza_finalizate %}6{% else %}5{% endif %}"\n                                class="text-center text-muted py-4">\n                                {% if afiseaza_finalizate %}\n                                    Nu există remindere finalizate.\n                                {% else %}\n                                    Nu există remindere active.\n                                {% endif %}\n                            </td>\n                        </tr>\n                        {% endfor %}\n                    </tbody>\n                </table>\n            </div>\n        </div>\n    </div>\n</div>\n{% endblock %}\n'
template_path.write_text(template, encoding="utf-8")
print("OK: core/templates/core/reminders.html")

print("\n==============================================")
print("UPDATE APLICAT CU SUCCES.")
print("- manager + superadmin vad toate reminderele")
print("- coloana Creat de adaugata")
print("- proprietarul nu se schimba la editare")
